# Batch 2 — chalisas. Text checked against published versions; meanings are original (OmKiran Bhakti).
D, C, P, S, SO = "doha", "chaupai", "pad", "shloka", "doha"

LAKSHMI_CHALISA = [
 (D,"मातु लक्ष्मी करि कृपा, करो हृदय में वास।\nमनोकामना सिद्ध करि, पुरवहु मेरी आस॥","हे माँ लक्ष्मी, कृपा करके मेरे हृदय में बसिए और मेरी मनोकामना पूरी करके मेरी आशा पूरी कीजिए।"),
 (D,"यही मोर अरदास, हाथ जोड़ विनती करुं।\nसब विधि करौ सुवास, जय जननि जगदंबिका॥","हाथ जोड़कर यही विनती है — हे जगत की माता, हर तरह से मेरे घर में वास कीजिए। (सोरठा)"),
 (C,"सिन्धु सुता मैं सुमिरौ तोही।\nज्ञान बुद्धि विद्या दो मोही॥","हे समुद्र की पुत्री, मैं आपका स्मरण करता हूँ; मुझे ज्ञान, बुद्धि और विद्या दीजिए।"),
 (C,"तुम समान नहिं कोई उपकारी।\nसब विधि पुरवहु आस हमारी॥","आपके जैसा उपकार करने वाला कोई नहीं; हर तरह से हमारी आशा पूरी कीजिए।"),
 (C,"जय जय जगत जननि जगदम्बा।\nसबकी तुम ही हो अवलम्बा॥","हे जगत की जननी जगदंबा, आपकी जय हो; आप ही सबका सहारा हैं।"),
 (C,"तुम ही हो सब घट घट वासी।\nविनती यही हमारी खासी॥","आप हर हृदय में बसती हैं; हमारी यही खास विनती है।"),
 (C,"जगजननी जय सिन्धु कुमारी।\nदीनन की तुम हो हितकारी॥","हे जगजननी, समुद्र की पुत्री, आपकी जय हो; आप दीन-दुखियों का भला करती हैं।"),
 (C,"विनवौं नित्य तुमहिं महारानी।\nकृपा करौ जग जननि भवानी॥","हे महारानी, मैं रोज़ आपसे विनती करता हूँ; हे जगजननी भवानी, कृपा कीजिए।"),
 (C,"केहि विधि स्तुति करौं तिहारी।\nसुधि लीजै अपराध बिसारी॥","मैं किस तरह आपकी स्तुति करूँ? मेरे अपराध भुलाकर मेरी सुध लीजिए।"),
 (C,"कृपा दृष्टि चितववो मम ओरी।\nजगजननी विनती सुन मोरी॥","मेरी ओर कृपा-दृष्टि से देखिए; हे जगजननी, मेरी विनती सुनिए।"),
 (C,"ज्ञान बुद्धि जय सुख की दाता।\nसंकट हरो हमारी माता॥","हे ज्ञान, बुद्धि और सुख देने वाली माँ, आपकी जय हो; हमारे संकट हर लीजिए।"),
 (C,"क्षीरसिन्धु जब विष्णु मथायो।\nचौदह रत्न सिन्धु में पायो॥","जब विष्णु ने क्षीरसागर का मंथन करवाया, तब समुद्र से चौदह रत्न निकले।"),
 (C,"चौदह रत्न में तुम सुखरासी।\nसेवा कियो प्रभु बनि दासी॥","उन चौदह रत्नों में आप सुख की खान बनकर निकलीं और प्रभु की सेविका बनकर उनकी सेवा की।"),
 (C,"जब जब जन्म जहां प्रभु लीन्हा।\nरुप बदल तहं सेवा कीन्हा॥","प्रभु ने जब-जब जहाँ जन्म लिया, आपने रूप बदलकर वहीं उनकी सेवा की।"),
 (C,"स्वयं विष्णु जब नर तनु धारा।\nलीन्हेउ अवधपुरी अवतारा॥","जब स्वयं विष्णु ने मनुष्य शरीर धारण किया और अयोध्या में (राम रूप में) अवतार लिया,"),
 (C,"तब तुम प्रगट जनकपुर माहीं।\nसेवा कियो हृदय पुलकाहीं॥","तब आप जनकपुर में (सीता रूप में) प्रकट हुईं और प्रसन्न मन से उनकी सेवा की।"),
 (C,"अपनाया तोहि अन्तर्यामी।\nविश्व विदित त्रिभुवन की स्वामी॥","अंतर्यामी प्रभु ने आपको अपनाया; आप तीनों लोकों की स्वामिनी के रूप में विश्व-प्रसिद्ध हैं।"),
 (C,"तुम सम प्रबल शक्ति नहीं आनी।\nकहं लौ महिमा कहौं बखानी॥","आपके जैसी प्रबल शक्ति कोई दूसरी नहीं; मैं आपकी महिमा का कहाँ तक बखान करूँ।"),
 (C,"मन क्रम वचन करै सेवकाई।\nमन इच्छित वांछित फल पाई॥","जो मन, कर्म और वचन से आपकी सेवा करता है, वह मनचाहा फल पाता है।"),
 (C,"तजि छल कपट और चतुराई।\nपूजहिं विविध भांति मनलाई॥","छल-कपट और चालाकी छोड़कर, मन लगाकर तरह-तरह से आपकी पूजा करे।"),
 (C,"और हाल मैं कहौं बुझाई।\nजो यह पाठ करै मन लाई॥","और मैं समझाकर बताता हूँ — जो मन लगाकर यह पाठ करता है,"),
 (C,"ताको कोई कष्ट न होई।\nमन इच्छित पावै फल सोई॥","उसे कोई कष्ट नहीं होता और वह मनचाहा फल पाता है।"),
 (C,"त्राहि त्राहि जय दुःख निवारिणि।\nत्रिविध ताप भव बंधन हारिणी॥","हे दुख दूर करने वाली, रक्षा करो, रक्षा करो! आप तीनों तरह के कष्ट और संसार के बंधन हरती हैं।"),
 (C,"जो चालीसा पढ़ै पढ़ावै।\nध्यान लगाकर सुनै सुनावै॥","जो यह चालीसा पढ़ता-पढ़ाता है और ध्यान से सुनता-सुनाता है,"),
 (C,"ताकौ कोई न रोग सतावै।\nपुत्र आदि धन सम्पत्ति पावै॥","उसे कोई रोग नहीं सताता और वह संतान, धन और संपत्ति पाता है।"),
 (C,"पुत्रहीन अरु संपति हीना।\nअन्ध बधिर कोढ़ी अति दीना॥","जो संतानहीन हो, धनहीन हो, अंधा, बहरा, रोगी या बहुत दीन हो,"),
 (C,"विप्र बोलाय कै पाठ करावै।\nशंका दिल में कभी न लावै॥","वह ब्राह्मण को बुलाकर यह पाठ करवाए और मन में कभी शंका न लाए।"),
 (C,"पाठ करावै दिन चालीसा।\nता पर कृपा करैं गौरीसा॥","जो चालीस दिन यह पाठ करवाता है, उस पर गौरीपति शिव भी कृपा करते हैं।"),
 (C,"सुख सम्पत्ति बहुत सी पावै।\nकमी नहीं काहू की आवै॥","वह बहुत सुख-संपत्ति पाता है और उसे किसी चीज़ की कमी नहीं रहती।"),
 (C,"बारह मास करै जो पूजा।\nतेहि सम धन्य और नहिं दूजा॥","जो बारहों महीने पूजा करता है, उसके जैसा धन्य कोई दूसरा नहीं।"),
 (C,"प्रतिदिन पाठ करै मन माही।\nउन सम कोइ जग में कहुं नाहीं॥","जो रोज़ मन में यह पाठ करता है, उसके जैसा संसार में कोई नहीं।"),
 (C,"बहुविधि क्या मैं करौं बड़ाई।\nलेय परीक्षा ध्यान लगाई॥","मैं कितनी बड़ाई करूँ — ध्यान लगाकर खुद परख लीजिए।"),
 (C,"करि विश्वास करै व्रत नेमा।\nहोय सिद्ध उपजै उर प्रेमा॥","विश्वास के साथ नियम से व्रत करने पर काम सिद्ध होते हैं और हृदय में प्रेम उपजता है।"),
 (C,"जय जय जय लक्ष्मी भवानी।\nसब में व्यापित हो गुण खानी॥","हे लक्ष्मी भवानी, आपकी जय हो; हे गुणों की खान, आप सब में व्याप्त हैं।"),
 (C,"तुम्हरो तेज प्रबल जग माहीं।\nतुम सम कोउ दयालु कहुं नाहिं॥","संसार में आपका तेज प्रबल है; आपके जैसा दयालु कहीं कोई नहीं।"),
 (C,"मोहि अनाथ की सुधि अब लीजै।\nसंकट काटि भक्ति मोहि दीजै॥","मुझ अनाथ की अब सुध लीजिए; संकट काटकर मुझे अपनी भक्ति दीजिए।"),
 (C,"भूल चूक करि क्षमा हमारी।\nदर्शन दीजै दशा निहारी॥","हमारी भूल-चूक क्षमा कीजिए और हमारी दशा देखकर दर्शन दीजिए।"),
 (C,"बिन दर्शन व्याकुल अधिकारी।\nतुमहि अछत दुःख सहते भारी॥","आपके दर्शन बिना भक्त व्याकुल है; आपके रहते हुए भी वह भारी दुख सह रहा है।"),
 (C,"नहिं मोहिं ज्ञान बुद्धि है तन में।\nसब जानत हो अपने मन में॥","मुझमें न ज्ञान है न बुद्धि; आप अपने मन में सब जानती हैं।"),
 (C,"रुप चतुर्भुज करके धारण।\nकष्ट मोर अब करहु निवारण॥","चार भुजाओं वाला रूप धारण करके अब मेरे कष्ट दूर कीजिए।"),
 (C,"केहि प्रकार मैं करौं बड़ाई।\nज्ञान बुद्धि मोहि नहिं अधिकाई॥","मैं किस तरह आपकी बड़ाई करूँ, मेरे पास इतना ज्ञान और बुद्धि नहीं।"),
 (D,"त्राहि त्राहि दुख हारिणी, हरो वेगि सब त्रास।\nजयति जयति जय लक्ष्मी, करो शत्रु को नाश॥","हे दुख हरने वाली, रक्षा कीजिए, जल्दी सारे डर दूर कीजिए। हे लक्ष्मी, आपकी जय हो; शत्रुओं का नाश कीजिए।"),
 (D,"रामदास धरि ध्यान नित, विनय करत कर जोर।\nमातु लक्ष्मी दास पर, करहु दया की कोर॥","रामदास रोज़ ध्यान करके हाथ जोड़कर विनती करते हैं — हे माँ लक्ष्मी, इस दास पर थोड़ी दया कीजिए।"),
]

SHANI_CHALISA = [
 (D,"जय गणेश गिरिजा सुवन, मंगल करण कृपाल।\nदीनन के दुख दूर करि, कीजै नाथ निहाल॥","हे गिरिजा-पुत्र, मंगल करने वाले कृपालु गणेश, आपकी जय हो; दीनों के दुख दूर करके उन्हें निहाल कीजिए।"),
 (D,"जय जय श्री शनिदेव प्रभु, सुनहु विनय महाराज।\nकरहु कृपा हे रवि तनय, राखहु जन की लाज॥","हे शनिदेव प्रभु, आपकी जय हो; हे महाराज, विनती सुनिए। हे सूर्यपुत्र, कृपा करके भक्त की लाज रखिए।"),
 (C,"जयति जयति शनिदेव दयाला।\nकरत सदा भक्तन प्रतिपाला॥","हे दयालु शनिदेव, आपकी जय हो; आप सदा भक्तों का पालन करते हैं।"),
 (C,"चारि भुजा, तनु श्याम विराजै।\nमाथे रतन मुकुट छबि छाजै॥","आपकी चार भुजाएँ हैं, शरीर साँवला है और माथे पर रत्नों का मुकुट शोभा देता है।"),
 (C,"परम विशाल मनोहर भाला।\nटेढ़ी दृष्टि भृकुटि विकराला॥","आपका माथा विशाल और सुंदर है, दृष्टि टेढ़ी और भौंहें विकराल हैं।"),
 (C,"कुण्डल श्रवण चमाचम चमके।\nहिय माल मुक्तन मणि दमके॥","कानों में कुंडल चमकते हैं और छाती पर मोतियों-मणियों की माला दमकती है।"),
 (C,"कर में गदा त्रिशूल कुठारा।\nपल बिच करैं अरिहिं संहारा॥","हाथों में गदा, त्रिशूल और फरसा है; आप पल भर में शत्रुओं का संहार करते हैं।"),
 (C,"पिंगल, कृष्णों, छाया नन्दन।\nयम, कोणस्थ, रौद्र, दुखभंजन॥","पिंगल, कृष्ण, छायानंदन, यम, कोणस्थ, रौद्र, दुखभंजन —"),
 (C,"सौरी, मन्द, शनी, दश नामा।\nभानु पुत्र पूजहिं सब कामा॥","सौरी, मंद और शनि — ये आपके दस नाम हैं; सूर्यपुत्र की पूजा से सब काम बनते हैं।"),
 (C,"जा पर प्रभु प्रसन्न ह्वैं जाहीं।\nरंकहुँ राव करैं क्षण माहीं॥","जिस पर आप प्रसन्न हो जाते हैं, उस गरीब को भी पल भर में राजा बना देते हैं।"),
 (C,"पर्वतहू तृण होई निहारत।\nतृणहू को पर्वत करि डारत॥","आपकी दृष्टि से पर्वत भी तिनका हो जाता है और तिनका भी पर्वत बन जाता है।"),
 (C,"राज मिलत बन रामहिं दीन्हयो।\nकैकेइहुँ की मति हरि लीन्हयो॥","राज्य मिलने के समय श्रीराम को वनवास दिलाया और कैकेयी की बुद्धि फेर दी।"),
 (C,"बनहूँ में मृग कपट दिखाई।\nमातु जानकी गई चुराई॥","वन में कपटी (सोने का) हिरण दिखाया और माता सीता चुरा ली गईं।"),
 (C,"लखनहिं शक्ति विकल करिडारा।\nमचिगा दल में हाहाकारा॥","लक्ष्मण को शक्ति-बाण से व्याकुल कर दिया और (राम की) सेना में हाहाकार मच गया।"),
 (C,"रावण की गतिमति बौराई।\nरामचन्द्र सों बैर बढ़ाई॥","रावण की बुद्धि भ्रष्ट कर दी, जिससे उसने श्रीराम से बैर बढ़ाया।"),
 (C,"दियो कीट करि कंचन लंका।\nबजि बजरंग बीर की डंका॥","सोने की लंका को मिट्टी में मिला दिया और वीर बजरंगबली का डंका बज गया।"),
 (C,"नृप विक्रम पर तुहि पगु धारा।\nचित्र मयूर निगलि गै हारा॥","राजा विक्रमादित्य पर आपकी दशा आई, तो चित्र का मोर (खूँटी पर टँगा) हार निगल गया।"),
 (C,"हार नौलखा लाग्यो चोरी।\nहाथ पैर डरवाय तोरी॥","नौलखा हार की चोरी का आरोप लगा और उनके हाथ-पैर तुड़वा दिए गए।"),
 (C,"भारी दशा निकृष्ट दिखायो।\nतेलिहिं घर कोल्हू चलवायो॥","भारी और बुरी दशा दिखाई और तेली के घर कोल्हू चलवाया।"),
 (C,"विनय राग दीपक महं कीन्हयों।\nतब प्रसन्न प्रभु ह्वै सुख दीन्हयों॥","जब विक्रम ने दीपक राग में आपकी विनती की, तब आप प्रसन्न हुए और सुख दिया।"),
 (C,"हरिश्चन्द्र नृप नारि बिकानी।\nआपहुं भरे डोम घर पानी॥","राजा हरिश्चंद्र की पत्नी बिक गई और वे स्वयं डोम के घर पानी भरने लगे।"),
 (C,"तैसे नल पर दशा सिरानी।\nभूंजी मीन कूद गई पानी॥","वैसे ही राजा नल पर दशा आई, तो भुनी हुई मछली भी पानी में कूद गई।"),
 (C,"श्री शंकरहिं गह्यो जब जाई।\nपारवती को सती कराई॥","जब आपकी दशा शंकर जी पर आई, तो (पूर्वजन्म में) पार्वती को सती होना पड़ा।"),
 (C,"तनिक विलोकत ही करि रीसा।\nनभ उड़ि गयो गौरिसुत सीसा॥","जरा-सा क्रोध से देखते ही गौरी-पुत्र गणेश का सिर आकाश में उड़ गया।"),
 (C,"पाण्डव पर भै दशा तुम्हारी।\nबची द्रौपदी होति उघारी॥","पांडवों पर आपकी दशा आई, तो द्रौपदी निर्वस्त्र होने से (कृष्ण-कृपा से) बचीं।"),
 (C,"कौरव के भी गति मति मारयो।\nयुद्ध महाभारत करि डारयो॥","कौरवों की भी बुद्धि मार दी और महाभारत का युद्ध करवा दिया।"),
 (C,"रवि कहँ मुख महँ धरि तत्काला।\nलेकर कूदि परयो पाताला॥","आपने अपने ही पिता सूर्य को तुरंत मुँह में रख लिया और पाताल में कूद गए।"),
 (C,"शेष देव लखि विनती लाई।\nरवि को मुख ते दियो छुड़ाई॥","यह देखकर देवताओं ने विनती की, तब आपने सूर्य को मुँह से छोड़ दिया।"),
 (C,"वाहन प्रभु के सात सजाना।\nजग दिग्गज गर्दभ मृग स्वाना॥","प्रभु के सात वाहन हैं — हाथी, गधा, हिरण, कुत्ता,"),
 (C,"जम्बुक सिंह आदि नख धारी।\nसो फल ज्योतिष कहत पुकारी॥","सियार, सिंह आदि; ज्योतिष इनका अलग-अलग फल पुकारकर बताता है।"),
 (C,"गज वाहन लक्ष्मी गृह आवैं।\nहय ते सुख सम्पति उपजावैं॥","हाथी पर आने से घर में लक्ष्मी आती है, घोड़े पर आने से सुख-संपत्ति बढ़ती है।"),
 (C,"गर्दभ हानि करै बहु काजा।\nसिंह सिद्धकर राज समाजा॥","गधे पर आने से कामों में हानि होती है, सिंह पर आने से राज-समाज में सफलता मिलती है।"),
 (C,"जम्बुक बुद्धि नष्ट कर डारै।\nमृग दे कष्ट प्राण संहारै॥","सियार पर आने से बुद्धि नष्ट होती है, हिरण पर आने से प्राणों तक का कष्ट होता है।"),
 (C,"जब आवहिं प्रभु स्वान सवारी।\nचोरी आदि होय डर भारी॥","जब प्रभु कुत्ते की सवारी पर आते हैं, तब चोरी आदि का भारी डर होता है।"),
 (C,"तैसहि चारि चरण यह नामा।\nस्वर्ण लौह चाँदी अरु तामा॥","इसी तरह आपके चार चरण (पाद) हैं — सोना, लोहा, चाँदी और ताँबा।"),
 (C,"लौह चरण पर जब प्रभु आवैं।\nधन जन सम्पत्ति नष्ट करावैं॥","जब प्रभु लोहे के चरण से आते हैं, तब धन, परिवार और संपत्ति की हानि कराते हैं।"),
 (C,"समता ताम्र रजत शुभकारी।\nस्वर्ण सर्व सुख मंगल भारी॥","ताँबा और चाँदी बराबर शुभ हैं, और सोने का चरण सब सुख और भारी मंगल देता है।"),
 (C,"जो यह शनि चरित्र नित गावै।\nकबहुं न दशा निकृष्ट सतावै॥","जो रोज़ शनि का यह चरित्र गाता है, उसे बुरी दशा कभी नहीं सताती।"),
 (C,"अद्भुत नाथ दिखावैं लीला।\nकरैं शत्रु के नशि बलि ढीला॥","नाथ अद्भुत लीला दिखाते हैं और शत्रुओं का बल ढीला कर देते हैं।"),
 (C,"जो पण्डित सुयोग्य बुलवाई।\nविधिवत शनि ग्रह शांति कराई॥","जो योग्य पंडित बुलाकर विधि से शनि ग्रह की शांति करवाता है,"),
 (C,"पीपल जल शनि दिवस चढ़ावत।\nदीप दान दै बहु सुख पावत॥","और शनिवार को पीपल पर जल चढ़ाकर दीपदान करता है, वह बहुत सुख पाता है।"),
 (C,"कहत राम सुन्दर प्रभु दासा।\nशनि सुमिरत सुख होत प्रकाशा॥","प्रभु के दास रामसुंदर कहते हैं — शनि का स्मरण करने से सुख का प्रकाश होता है।"),
 (D,"पाठ शनिश्चर देव को, की हों भक्त तैयार।\nकरत पाठ चालीस दिन, हो भवसागर पार॥","भक्तों के लिए तैयार किया गया शनिदेव का यह पाठ जो चालीस दिन करता है, वह संसार-सागर से पार हो जाता है।"),
]

KRISHNA_CHALISA = [
 (D,"बंशी शोभित कर मधुर, नील जलद तन श्याम।\nअरुण अधर जनु बिम्बफल, नयन कमल अभिराम॥","हाथ में मधुर बाँसुरी, नीले बादल जैसा साँवला शरीर, बिंबफल जैसे लाल होंठ और कमल जैसी सुंदर आँखें।"),
 (D,"पूर्ण इन्द्र, अरविन्द मुख, पीताम्बर शुभ साज।\nजय मनमोहन मदन छवि, कृष्णचन्द्र महाराज॥","पूर्ण चंद्रमा और कमल जैसा मुख, सुंदर पीला वस्त्र — कामदेव जैसी छवि वाले मनमोहन कृष्णचंद्र महाराज की जय।"),
 (C,"जय यदुनन्दन जय जगवन्दन।\nजय वसुदेव देवकी नन्दन॥","हे यदुवंश के नंदन, जगत के वंदनीय, वसुदेव-देवकी के पुत्र, आपकी जय हो।"),
 (C,"जय यशुदा सुत नन्द दुलारे।\nजय प्रभु भक्तन के दृग तारे॥","हे यशोदा के पुत्र, नंद के दुलारे, भक्तों की आँखों के तारे, आपकी जय हो।"),
 (C,"जय नट-नागर नाग नथैया।\nकृष्ण कन्हैया धेनु चरैया॥","हे नटनागर, कालिय नाग को नाथने वाले, गायें चराने वाले कृष्ण कन्हैया, आपकी जय हो।"),
 (C,"पुनि नख पर प्रभु गिरिवर धारो।\nआओ दीनन कष्ट निवारो॥","हे प्रभु, फिर से नख पर गोवर्धन उठाओ, आओ और दीनों के कष्ट दूर करो।"),
 (C,"वंशी मधुर अधर धरी तेरी।\nहोवे पूर्ण मनोरथ मेरो॥","होंठों पर मधुर बाँसुरी रखकर आओ, ताकि मेरा मनोरथ पूरा हो।"),
 (C,"आओ हरि पुनि माखन चाखो।\nआज लाज भारत की राखो॥","हे हरि, आओ फिर माखन चखो और आज भारत की लाज रखो।"),
 (C,"गोल कपोल, चिबुक अरुणारे।\nमृदु मुस्कान मोहिनी डारे॥","गोल गाल, लाल ठोड़ी और कोमल मुस्कान सबको मोह लेती है।"),
 (C,"रंजित राजिव नयन विशाला।\nमोर मुकुट वैजयंती माला॥","लाल कमल जैसी बड़ी आँखें, मोर-मुकुट और वैजयंती माला है।"),
 (C,"कुण्डल श्रवण पीतपट आछे।\nकटि किंकणी काछन काछे॥","कानों में कुंडल, सुंदर पीला वस्त्र और कमर में करधनी बँधी है।"),
 (C,"नील जलज सुन्दर तनु सोहे।\nछवि लखि, सुर नर मुनिमन मोहे॥","नीले कमल जैसा सुंदर शरीर है; यह छवि देखकर देवता, मनुष्य और मुनि मोहित हो जाते हैं।"),
 (C,"मस्तक तिलक, अलक घुंघराले।\nआओ कृष्ण बांसुरी वाले॥","माथे पर तिलक और घुँघराले बाल — आओ, बाँसुरी वाले कृष्ण।"),
 (C,"करि पय पान, पुतनहि तारयो।\nअका बका कागासुर मारयो॥","दूध पीते-पीते पूतना को तार दिया और अघासुर, बकासुर, कागासुर को मारा।"),
 (C,"मधुवन जलत अग्नि जब ज्वाला।\nभै शीतल, लखितहिं नन्दलाला॥","जब मधुवन आग की ज्वाला में जल रहा था, नंदलाला के देखते ही वह शीतल हो गया।"),
 (C,"सुरपति जब ब्रज चढ़यो रिसाई।\nमूसर धार वारि वर्षाई॥","जब इंद्र क्रोध में ब्रज पर चढ़ आए और मूसलाधार पानी बरसाया,"),
 (C,"लगत-लगत ब्रज चहन बहायो।\nगोवर्धन नखधारि बचायो॥","ब्रज बह जाने ही वाला था, तब आपने गोवर्धन को नख पर उठाकर बचाया।"),
 (C,"लखि यसुदा मन भ्रम अधिकाई।\nमुख महं चौदह भुवन दिखाई॥","यशोदा के मन में भ्रम बढ़ा, तो आपने अपने मुख में चौदह भुवन दिखा दिए।"),
 (C,"दुष्ट कंस अति उधम मचायो।\nकोटि कमल जब फूल मंगायो॥","दुष्ट कंस ने बहुत उत्पात मचाया और (यमुना के कालिय-कुंड से) करोड़ों कमल मँगवाए।"),
 (C,"नाथि कालियहिं तब तुम लीन्हें।\nचरणचिन्ह दै निर्भय किन्हें॥","तब आपने कालिय नाग को नाथा और उसके फन पर चरण-चिह्न देकर उसे निर्भय किया।"),
 (C,"करि गोपिन संग रास विलासा।\nसबकी पूरण करी अभिलाषा॥","गोपियों के साथ रास रचाकर सबकी इच्छा पूरी की।"),
 (C,"केतिक महा असुर संहारयो।\nकंसहि केस पकड़ि दै मारयो॥","कितने ही बड़े असुरों का संहार किया और कंस को बाल पकड़कर मार गिराया।"),
 (C,"मात-पिता की बन्दि छुड़ाई।\nउग्रसेन कहं राज दिलाई॥","माता-पिता को कैद से छुड़ाया और उग्रसेन को राज्य दिलाया।"),
 (C,"महि से मृतक छहों सुत लायो।\nमातु देवकी शोक मिटायो॥","मरे हुए छहों भाइयों को लाकर माता देवकी का शोक मिटाया।"),
 (C,"भौमासुर मुर दैत्य संहारी।\nलाये षट दश सहसकुमारी॥","भौमासुर और मुर दैत्य को मारकर सोलह हज़ार कन्याओं को मुक्त कराकर लाए।"),
 (C,"दै भीमहिं तृण चीर सहारा।\nजरासिंधु राक्षस कहं मारा॥","भीम को तिनका चीरकर इशारा दिया और जरासंध को मरवाया।"),
 (C,"असुर बकासुर आदिक मारयो।\nभक्तन के तब कष्ट निवारियो॥","बकासुर आदि असुरों को मारकर भक्तों के कष्ट दूर किए।"),
 (C,"दीन सुदामा के दुःख टारयो।\nतंदुल तीन मूंठ मुख डारयो॥","गरीब सुदामा के दुख दूर किए और उनके तीन मुट्ठी चावल खाए।"),
 (C,"प्रेम के साग विदुर घर मांगे।\nदुर्योधन के मेवा त्यागे॥","प्रेम के कारण विदुर के घर साग माँगकर खाया और दुर्योधन के मेवे त्याग दिए।"),
 (C,"लखि प्रेम की महिमा भारी।\nऐसे श्याम दीन हितकारी॥","प्रेम की ऐसी भारी महिमा देखिए — ऐसे हैं दीनों का भला करने वाले श्याम।"),
 (C,"भारत के पारथ रथ हांके।\nलिए चक्र कर नहिं बल ताके॥","महाभारत में अर्जुन का रथ हाँका; हाथ में चक्र लिया, फिर भी अपना बल नहीं दिखाया।"),
 (C,"निज गीता के ज्ञान सुनाये।\nभक्तन ह्रदय सुधा वर्षाये॥","अपनी गीता का ज्ञान सुनाकर भक्तों के हृदय में अमृत बरसाया।"),
 (C,"मीरा थी ऐसी मतवाली।\nविष पी गई बजाकर ताली॥","मीरा ऐसी दीवानी थीं कि ताली बजाकर विष पी गईं।"),
 (C,"राना भेजा सांप पिटारी।\nशालिग्राम बने बनवारी॥","राणा ने पिटारी में साँप भेजा, तो बनवारी शालिग्राम बन गए।"),
 (C,"निज माया तुम विधिहिं दिखायो।\nउर ते संशय सकल मिटायो॥","आपने ब्रह्मा को अपनी माया दिखाई और उनके मन के सारे संशय मिटा दिए।"),
 (C,"तब शत निन्दा करी तत्काला।\nजीवन मुक्त भयो शिशुपाला॥","सौ बार निंदा करते ही शिशुपाल (आपके हाथों) तुरंत मुक्त हो गया।"),
 (C,"जबहिं द्रौपदी टेर लगाई।\nदीनानाथ लाज अब जाई॥","जब द्रौपदी ने पुकार लगाई — हे दीनानाथ, अब लाज जा रही है,"),
 (C,"तुरतहिं वसन बने नन्दलाला।\nबढ़े चीर भै अरि मुँह काला॥","तुरंत नंदलाला वस्त्र बन गए; चीर बढ़ता गया और शत्रुओं का मुँह काला हुआ।"),
 (C,"अस नाथ के नाथ कन्हैया।\nडूबत भंवर बचावत नैया॥","ऐसे हैं नाथों के नाथ कन्हैया, जो भँवर में डूबती नाव बचा लेते हैं।"),
 (C,"सुन्दरदास आस उर धारी।\nदयादृष्टि कीजै बनवारी॥","सुंदरदास मन में आशा रखते हैं — हे बनवारी, दया-दृष्टि कीजिए।"),
 (C,"नाथ सकल मम कुमति निवारो।\nक्षमहु बेगि अपराध हमारो॥","हे नाथ, मेरी सारी कुबुद्धि दूर कीजिए और जल्दी हमारे अपराध क्षमा कीजिए।"),
 (C,"खोलो पट अब दर्शन दीजै।\nबोलो कृष्ण कन्हैया की जै॥","अब पट खोलकर दर्शन दीजिए — बोलो कृष्ण कन्हैया की जय!"),
 (D,"यह चालीसा कृष्ण का, पाठ करै उर धारि।\nअष्ट सिद्धि नवनिधि फल, लहै पदारथ चारि॥","जो हृदय में धारण करके कृष्ण की यह चालीसा पढ़ता है, वह आठ सिद्धियाँ, नौ निधियाँ और चारों पुरुषार्थ पाता है।"),
]

RAM_CHALISA = [
 (S,"आदौ राम तपोवनादि गमनं हत्वा मृगं काञ्चनं\nवैदेही हरणं जटायु मरणं सुग्रीव संभाषणम्।\nबालीनिर्दलनं समुद्रतरणं लङ्कापुरीदाहनं\nपश्चाद्रावणकुम्भकर्णहननं एतद्धि रामायणम्॥","(एक श्लोकी रामायण) राम का वन जाना, सोने के हिरण का वध, सीता-हरण, जटायु की मृत्यु, सुग्रीव से मित्रता, बाली-वध, समुद्र पार करना, लंका-दहन, फिर रावण और कुंभकर्ण का वध — यही पूरी रामायण है।"),
 (C,"श्री रघुबीर भक्त हितकारी।\nसुनि लीजै प्रभु अरज हमारी॥","हे भक्तों का भला करने वाले रघुवीर, हमारी विनती सुन लीजिए।"),
 (C,"निशि दिन ध्यान धरै जो कोई।\nता सम भक्त और नहिं होई॥","जो दिन-रात आपका ध्यान करता है, उसके जैसा भक्त कोई नहीं।"),
 (C,"ध्यान धरे शिवजी मन माहीं।\nब्रह्मा इन्द्र पार नहिं पाहीं॥","शिव जी मन में आपका ध्यान करते हैं; ब्रह्मा और इंद्र भी आपका पार नहीं पाते।"),
 (C,"जय जय जय रघुनाथ कृपाला।\nसदा करो सन्तन प्रतिपाला॥","हे कृपालु रघुनाथ, आपकी जय हो; आप सदा संतों का पालन करते हैं।"),
 (C,"दूत तुम्हार वीर हनुमाना।\nजासु प्रभाव तिहूँ पुर जाना॥","वीर हनुमान आपके दूत हैं, जिनका प्रभाव तीनों लोक जानते हैं।"),
 (C,"तुव भुजदण्ड प्रचण्ड कृपाला।\nरावण मारि सुरन प्रतिपाला॥","हे कृपालु, आपकी भुजाएँ प्रचंड हैं; आपने रावण को मारकर देवताओं की रक्षा की।"),
 (C,"तुम अनाथ के नाथ गोसाईं।\nदीनन के हो सदा सहाई॥","हे स्वामी, आप अनाथों के नाथ और दीनों के सदा सहायक हैं।"),
 (C,"ब्रह्मादिक तव पार न पावैं।\nसदा ईश तुम्हरो यश गावैं॥","ब्रह्मा आदि भी आपका पार नहीं पाते; शिव सदा आपका यश गाते हैं।"),
 (C,"चारिउ वेद भरत हैं साखी।\nतुम भक्तन की लज्जा राखी॥","चारों वेद गवाह हैं कि आपने सदा भक्तों की लाज रखी।"),
 (C,"गुण गावत शारद मन माहीं।\nसुरपति ताको पार न पाहीं॥","सरस्वती मन में आपके गुण गाती हैं; इंद्र भी आपका पार नहीं पाते।"),
 (C,"नाम तुम्हार लेत जो कोई।\nता सम धन्य और नहिं होई॥","जो आपका नाम लेता है, उसके जैसा धन्य कोई नहीं।"),
 (C,"राम नाम है अपरम्पारा।\nचारिहु वेदन जाहि पुकारा॥","राम नाम अपरंपार है, जिसे चारों वेद पुकारते हैं।"),
 (C,"गणपति नाम तुम्हारो लीन्हों।\nतिनको प्रथम पूज्य तुम कीन्हों॥","गणपति ने आपका नाम लिया, तो आपने उन्हें प्रथम पूज्य बना दिया।"),
 (C,"शेष रटत नित नाम तुम्हारा।\nमहि को भार शीश पर धारा॥","शेषनाग रोज़ आपका नाम रटते हैं और पृथ्वी का भार सिर पर उठाते हैं।"),
 (C,"फूल समान रहत सो भारा।\nपावत कोउ न तुम्हरो पारा॥","आपके नाम से वह भार फूल जैसा हल्का रहता है; आपका पार कोई नहीं पाता।"),
 (C,"भरत नाम तुम्हरो उर धारो।\nतासों कबहुँ न रण में हारो॥","भरत ने आपका नाम हृदय में धारण किया, इसलिए वे कभी युद्ध में नहीं हारे।"),
 (C,"नाम शत्रुहन हृदय प्रकाशा।\nसुमिरत होत शत्रु कर नाशा॥","शत्रुघ्न के हृदय में आपका नाम प्रकाशित है; स्मरण से शत्रुओं का नाश होता है।"),
 (C,"लषन तुम्हारे आज्ञाकारी।\nसदा करत सन्तन रखवारी॥","लक्ष्मण आपके आज्ञाकारी हैं और सदा संतों की रखवाली करते हैं।"),
 (C,"ताते रण जीते नहिं कोई।\nयुद्ध जुरे यमहूँ किन होई॥","इसलिए युद्ध में उन्हें कोई नहीं जीत सकता, चाहे सामने यमराज ही क्यों न हों।"),
 (C,"महा लक्ष्मी धर अवतारा।\nसब विधि करत पाप को छारा॥","महालक्ष्मी (सीता रूप में) अवतार लेकर हर तरह से पापों को राख कर देती हैं।"),
 (C,"सीता राम पुनीता गायो।\nभुवनेश्वरी प्रभाव दिखायो॥","सीता-राम का पवित्र यश गाया गया; भुवनेश्वरी (सीता) ने अपना प्रभाव दिखाया।"),
 (C,"घट सों प्रकट भई सो आई।\nजाको देखत चन्द्र लजाई॥","वे (भूमि में दबे) घड़े से प्रकट हुईं, जिन्हें देखकर चंद्रमा भी लजा जाए।"),
 (C,"सो तुमरे नित पांव पलोटत।\nनवो निद्धि चरणन में लोटत॥","वे रोज़ आपके चरण दबाती हैं और नौ निधियाँ आपके चरणों में लोटती हैं।"),
 (C,"सिद्धि अठारह मंगल कारी।\nसो तुम पर जावै बलिहारी॥","मंगल करने वाली अठारह सिद्धियाँ आप पर बलिहारी जाती हैं।"),
 (C,"औरहु जो अनेक प्रभुताई।\nसो सीतापति तुमहिं बनाई॥","और भी जितनी प्रभुता है, हे सीतापति, वह सब आपने ही बनाई है।"),
 (C,"इच्छा ते कोटिन संसारा।\nरचत न लागत पल की बारा॥","अपनी इच्छा से करोड़ों संसार रचने में आपको पल भर भी नहीं लगता।"),
 (C,"जो तुम्हरे चरनन चित लावै।\nताको मुक्ति अवसि हो जावै॥","जो आपके चरणों में मन लगाता है, उसकी मुक्ति अवश्य होती है।"),
 (C,"सुनहु राम तुम तात हमारे।\nतुमहिं भरत कुल पूज्य प्रचारे॥","हे राम, सुनिए — आप हमारे पिता हैं; आप ही भरत-कुल (भारत) के पूज्य हैं।"),
 (C,"तुमहिं देव कुल देव हमारे।\nतुम गुरु देव प्राण के प्यारे॥","आप ही हमारे देव और कुलदेव हैं; आप ही गुरु और प्राणों से प्यारे हैं।"),
 (C,"जो कुछ हो सो तुमहीं राजा।\nजय जय जय प्रभु राखो लाजा॥","हे राजा, जो कुछ है वह आप ही हैं; हे प्रभु, आपकी जय हो, लाज रखिए।"),
 (C,"रामा आत्मा पोषण हारे।\nजय जय जय दशरथ के प्यारे॥","हे राम, आप आत्मा का पोषण करने वाले हैं; दशरथ के प्यारे, आपकी जय हो।"),
 (C,"जय जय जय प्रभु ज्योति स्वरूपा।\nनिगुण ब्रह्म अखण्ड अनूपा॥","हे ज्योति-स्वरूप प्रभु, आपकी जय हो; आप निर्गुण, अखंड और अनुपम ब्रह्म हैं।"),
 (C,"सत्य सत्य जय सत्यब्रत स्वामी।\nसत्य सनातन अन्तर्यामी॥","हे सत्यव्रती स्वामी, आप सत्य हैं, सनातन हैं और सबके मन की जानते हैं।"),
 (C,"सत्य भजन तुम्हरो जो गावै।\nसो निश्चय चारों फल पावै॥","जो सच्चे मन से आपका भजन गाता है, वह निश्चय ही चारों फल पाता है।"),
 (C,"सत्य शपथ गौरीपति कीन्हीं।\nतुमने भक्तहिं सब सिद्धि दीन्हीं॥","गौरीपति शिव ने सच्ची शपथ खाकर कहा है कि आपने भक्तों को सब सिद्धियाँ दी हैं।"),
 (C,"ज्ञान हृदय दो ज्ञान स्वरूपा।\nनमो नमो जय जापति भूपा॥","हे ज्ञान-स्वरूप, हृदय में ज्ञान दीजिए; हे जानकीपति भूप, आपको नमस्कार।"),
 (C,"धन्य धन्य तुम धन्य प्रतापा।\nनाम तुम्हार हरत संतापा॥","आप धन्य हैं, आपका प्रताप धन्य है; आपका नाम संताप हरता है।"),
 (C,"सत्य शुद्ध देवन मुख गाया।\nबजी दुन्दुभी शंख बजाया॥","देवताओं ने आपका सच्चा और शुद्ध यश गाया, नगाड़े और शंख बजाए।"),
 (C,"सत्य सत्य तुम सत्य सनातन।\nतुमहीं हो हमरे तन मन धन॥","आप सत्य हैं, सनातन हैं; आप ही हमारे तन, मन और धन हैं।"),
 (C,"याको पाठ करे जो कोई।\nज्ञान प्रकट ताके उर होई॥","जो इसका पाठ करता है, उसके हृदय में ज्ञान प्रकट होता है।"),
 (C,"आवागमन मिटै तिहि केरा।\nसत्य वचन माने शिव मेरा॥","उसका जन्म-मरण का चक्र मिट जाता है — मेरे शिव की यह सच्ची बात मानिए।"),
 (C,"और आस मन में जो ल्यावै।\nतुलसी दल अरु फूल चढ़ावै॥","जो मन में कोई और कामना रखे, वह तुलसी-दल और फूल चढ़ाए,"),
 (C,"साग पत्र सो भोग लगावै।\nसो नर सकल सिद्धता पावै॥","साग-पत्ते का भोग लगाए — वह मनुष्य सारी सिद्धियाँ पाता है।"),
 (C,"अन्त समय रघुबर पुर जाई।\nजहाँ जन्म हरि भक्त कहाई॥","अंत समय में वह श्रीराम के धाम जाता है और जहाँ भी जन्म ले, हरि-भक्त कहलाता है।"),
 (C,"श्री हरि दास कहै अरु गावै।\nसो वैकुण्ठ धाम को पावै॥","हरिदास कहते हैं — जो इसे कहता और गाता है, वह वैकुंठ धाम पाता है।"),
 (D,"सात दिवस जो नेम कर, पाठ करे चित लाय।\nहरिदास हरिकृपा से, अवसि भक्ति को पाय॥","जो सात दिन नियम से मन लगाकर पाठ करता है, वह हरि की कृपा से अवश्य भक्ति पाता है।"),
 (D,"राम चालीसा जो पढ़े, रामचरण चित लाय।\nजो इच्छा मन में करै, सकल सिद्ध हो जाय॥","जो राम के चरणों में मन लगाकर राम चालीसा पढ़ता है, उसकी हर मनोकामना पूरी होती है।"),
]

VISHNU_CHALISA = [
 (D,"विष्णु सुनिए विनय, सेवक की चितलाय।\nकीरत कुछ वर्णन करूं, दीजै ज्ञान बताय॥","हे विष्णु, मन लगाकर सेवक की विनती सुनिए; मैं आपकी कीर्ति का कुछ वर्णन करूँ, मुझे ज्ञान दीजिए।"),
 (C,"नमो विष्णु भगवान खरारी।\nकष्ट नशावन अखिल बिहारी॥","हे भगवान विष्णु, असुरों के शत्रु, कष्ट मिटाने वाले, सारे जगत में विहार करने वाले, आपको नमस्कार।"),
 (C,"प्रबल जगत में शक्ति तुम्हारी।\nत्रिभुवन फैल रही उजियारी॥","संसार में आपकी शक्ति प्रबल है; तीनों लोकों में आपका उजाला फैला है।"),
 (C,"सुन्दर रूप मनोहर सूरत।\nसरल स्वभाव मोहनी मूरत॥","आपका रूप सुंदर, चेहरा मनोहर, स्वभाव सरल और मूर्ति मोहक है।"),
 (C,"तन पर पीतांबर अति सोहत।\nबैजन्ती माला मन मोहत॥","शरीर पर पीला वस्त्र बहुत सुंदर लगता है और वैजयंती माला मन मोह लेती है।"),
 (C,"शंख चक्र कर गदा बिराजे।\nदेखत दैत्य असुर दल भाजे॥","हाथों में शंख, चक्र और गदा हैं, जिन्हें देखकर दैत्यों की सेना भाग जाती है।"),
 (C,"सत्य धर्म मद लोभ न गाजे।\nकाम क्रोध मद लोभ न छाजे॥","आपमें सत्य और धर्म है; काम, क्रोध, अहंकार और लोभ आपको छू भी नहीं सकते।"),
 (C,"संतभक्त सज्जन मनरंजन।\nदनुज असुर दुष्टन दल गंजन॥","आप संतों, भक्तों और सज्जनों का मन प्रसन्न करते हैं और दुष्ट असुरों का नाश करते हैं।"),
 (C,"सुख उपजाय कष्ट सब भंजन।\nदोष मिटाय करत जन सज्जन॥","आप सुख देते हैं, सब कष्ट तोड़ते हैं और दोष मिटाकर लोगों को सज्जन बनाते हैं।"),
 (C,"पाप काट भव सिंधु उतारण।\nकष्ट नाशकर भक्त उबारण॥","आप पाप काटकर संसार-सागर से पार उतारते हैं और कष्ट मिटाकर भक्तों को बचाते हैं।"),
 (C,"करत अनेक रूप प्रभु धारण।\nकेवल आप भक्ति के कारण॥","हे प्रभु, आप केवल भक्ति के कारण अनेक रूप धारण करते हैं।"),
 (C,"धरणि धेनु बन तुमहिं पुकारा।\nतब तुम रूप राम का धारा॥","जब धरती ने गाय बनकर आपको पुकारा, तब आपने राम का रूप धारण किया।"),
 (C,"भार उतार असुर दल मारा।\nरावण आदिक को संहारा॥","धरती का भार उतारा, असुरों को मारा और रावण आदि का संहार किया।"),
 (C,"आप वराह रूप बनाया।\nहरण्याक्ष को मार गिराया॥","आपने वराह का रूप बनाया और हिरण्याक्ष को मार गिराया।"),
 (C,"धर मत्स्य तन सिंधु बनाया।\nचौदह रतनन को निकलाया॥","मछली का रूप धरकर समुद्र में (वेदों की रक्षा की) और चौदह रत्न निकलवाए।"),
 (C,"अमिलख असुरन द्वंद मचाया।\nरूप मोहनी आप दिखाया॥","जब (अमृत के लिए) असुरों ने झगड़ा मचाया, तब आपने मोहिनी रूप दिखाया।"),
 (C,"देवन को अमृत पान कराया।\nअसुरन को छवि से बहलाया॥","देवताओं को अमृत पिलाया और असुरों को अपनी छवि से बहला दिया।"),
 (C,"कूर्म रूप धर सिंधु मझाया।\nमंद्राचल गिरि तुरत उठाया॥","कछुए का रूप धरकर समुद्र-मंथन कराया और मंदराचल पर्वत तुरंत उठा लिया।"),
 (C,"शंकर का तुम फन्द छुड़ाया।\nभस्मासुर को रूप दिखाया॥","आपने शंकर जी को संकट से छुड़ाया और भस्मासुर को (मोहिनी) रूप दिखाया।"),
 (C,"वेदन को जब असुर डुबाया।\nकर प्रबंध उन्हें ढूंढवाया॥","जब असुर ने वेदों को (समुद्र में) डुबा दिया, तब आपने उन्हें ढूँढकर निकाला।"),
 (C,"मोहित बनकर खलहि नचाया।\nउसही कर से भस्म कराया॥","मोहिनी बनकर उस दुष्ट (भस्मासुर) को नचाया और उसी के हाथ से उसे भस्म करवाया।"),
 (C,"असुर जलंधर अति बलदाई।\nशंकर से उन कीन्ह लडाई॥","बहुत बलशाली असुर जलंधर ने शंकर जी से युद्ध किया।"),
 (C,"हार पार शिव सकल बनाई।\nकीन सती से छल खल जाई॥","शिव के सारे प्रयास के बाद भी वह दुष्ट नहीं हारा और उसने पार्वती से छल करना चाहा।"),
 (C,"सुमिरन कीन तुम्हें शिवरानी।\nबतलाई सब विपत कहानी॥","तब पार्वती जी ने आपका स्मरण किया और सारी विपत्ति की कहानी बताई।"),
 (C,"तब तुम बने मुनीश्वर ज्ञानी।\nवृन्दा की सब सुरति भुलानी॥","तब आप ज्ञानी मुनि बने और (जलंधर की पत्नी) वृंदा की सुध-बुध भुला दी।"),
 (C,"देखत तीन दनुज शैतानी।\nवृन्दा आय तुम्हें लपटानी॥","उस दानव की माया देखकर वृंदा आकर आपसे लिपट गई।"),
 (C,"हो स्पर्श धर्म क्षति मानी।\nहना असुर उर शिव शैतानी॥","स्पर्श से उसका सतीत्व-धर्म टूटा, और तब शिव ने उस असुर को मार डाला।"),
 (C,"तुमने ध्रुव प्रहलाद उबारे।\nहिरणाकुश आदिक खल मारे॥","आपने ध्रुव और प्रह्लाद का उद्धार किया और हिरण्यकशिपु आदि दुष्टों को मारा।"),
 (C,"गणिका और अजामिल तारे।\nबहुत भक्त भव सिन्धु उतारे॥","आपने गणिका और अजामिल को तारा और बहुत से भक्तों को संसार-सागर से पार किया।"),
 (C,"हरहु सकल संताप हमारे।\nकृपा करहु हरि सिरजन हारे॥","हे सृष्टि रचने वाले हरि, कृपा करके हमारे सब संताप हर लीजिए।"),
 (C,"देखहुं मैं निज दरश तुम्हारे।\nदीन बन्धु भक्तन हितकारे॥","हे दीनबंधु, भक्तों का भला करने वाले, मैं आपके दर्शन पाऊँ।"),
 (C,"चहत आपका सेवक दर्शन।\nकरहु दया अपनी मधुसूदन॥","हे मधुसूदन, आपका सेवक दर्शन चाहता है; अपनी दया कीजिए।"),
 (C,"जानूं नहीं योग्य जप पूजन।\nहोय यज्ञ स्तुति अनुमोदन॥","मैं जप, पूजा, यज्ञ और स्तुति की सही विधि नहीं जानता।"),
 (C,"शीलदया सन्तोष सुलक्षण।\nविदित नहीं व्रतबोध विलक्षण॥","शील, दया, संतोष जैसे अच्छे गुण और व्रत का ज्ञान भी मुझे नहीं है।"),
 (C,"करहुं आपका किस विधि पूजन।\nकुमति विलोक होत दुख भीषण॥","मैं किस विधि से आपकी पूजा करूँ? अपनी कुबुद्धि देखकर मुझे भारी दुख होता है।"),
 (C,"करहुं प्रणाम कौन विधि सुमिरण।\nकौन भांति मैं करहु समर्पण॥","किस तरह प्रणाम करूँ, कैसे स्मरण करूँ और कैसे स्वयं को समर्पित करूँ?"),
 (C,"सुर मुनि करत सदा सेवकाई।\nहर्षित रहत परम गति पाई॥","देवता और मुनि सदा आपकी सेवा करते हैं और परम गति पाकर प्रसन्न रहते हैं।"),
 (C,"दीन दुखिन पर सदा सहाई।\nनिज जन जान लेव अपनाई॥","आप दीन-दुखियों के सदा सहायक हैं; मुझे अपना जानकर अपना लीजिए।"),
 (C,"पाप दोष संताप नशाओ।\nभव-बंधन से मुक्त कराओ॥","मेरे पाप, दोष और संताप नष्ट कीजिए और संसार के बंधन से मुक्त कीजिए।"),
 (C,"सुख संपत्ति दे सुख उपजाओ।\nनिज चरनन का दास बनाओ॥","सुख-संपत्ति देकर सुख बढ़ाइए और मुझे अपने चरणों का दास बनाइए।"),
 (C,"निगम सदा ये विनय सुनावै।\nपढ़ै सुनै सो जन सुख पावै॥","वेद सदा यह विनती सुनाते हैं; जो इसे पढ़ता-सुनता है, वह सुख पाता है।"),
]

SARASWATI_CHALISA = [
 (D,"जनक जननि पद्मरज, निज मस्तक पर धरि।\nबन्दौं मातु सरस्वती, बुद्धि बल दे दातारि॥","माता-पिता के चरणों की धूल माथे पर लगाकर मैं माँ सरस्वती की वंदना करता हूँ; हे दाता, बुद्धि और बल दीजिए।"),
 (D,"पूर्ण जगत में व्याप्त तव, महिमा अमित अनंतु।\nदुष्जनों के पाप को, मातु तु ही अब हन्तु॥","आपकी असीम और अनंत महिमा सारे जगत में फैली है; हे माँ, दुष्टों के पाप अब आप ही नष्ट कीजिए।"),
 (C,"जय श्री सकल बुद्धि बलरासी।\nजय सर्वज्ञ अमर अविनाशी॥","हे सारी बुद्धि और बल की खान, सब कुछ जानने वाली, अमर और अविनाशी माँ, आपकी जय हो।"),
 (C,"जय जय जय वीणाकर धारी।\nकरती सदा सुहंस सवारी॥","हे हाथ में वीणा धारण करने वाली, सुंदर हंस पर सवार माँ, आपकी जय हो।"),
 (C,"रूप चतुर्भुज धारी माता।\nसकल विश्व अन्दर विख्याता॥","हे चार भुजाओं वाली माँ, आप पूरे विश्व में प्रसिद्ध हैं।"),
 (C,"जग में पाप बुद्धि जब होती।\nतब ही धर्म की फीकी ज्योति॥","जब संसार में पाप-बुद्धि बढ़ती है, तब धर्म की ज्योति फीकी पड़ जाती है।"),
 (C,"तब ही मातु का निज अवतारी।\nपाप हीन करती महतारी॥","तभी माँ अवतार लेकर संसार को पाप से मुक्त करती हैं।"),
 (C,"वाल्मीकिजी थे हत्यारा।\nतव प्रसाद जानै संसारा॥","वाल्मीकि जी पहले हत्यारे थे; आपकी कृपा (से वे ऋषि बने), यह संसार जानता है।"),
 (C,"रामचरित जो रचे बनाई।\nआदि कवि की पदवी पाई॥","उन्होंने रामचरित (रामायण) की रचना की और आदि कवि की पदवी पाई।"),
 (C,"कालिदास जो भये विख्याता।\nतेरी कृपा दृष्टि से माता॥","हे माँ, कालिदास भी आपकी कृपा-दृष्टि से ही प्रसिद्ध हुए।"),
 (C,"तुलसी सूर आदि विद्वाना।\nभये और जो ज्ञानी नाना॥","तुलसीदास, सूरदास आदि विद्वान और अनेक ज्ञानी हुए,"),
 (C,"तिन्ह न और रहेउ अवलम्बा।\nकेवल कृपा आपकी अम्बा॥","उनका कोई और सहारा नहीं था, हे अम्बा, केवल आपकी कृपा थी।"),
 (C,"करहु कृपा सोइ मातु भवानी।\nदुखित दीन निज दासहि जानी॥","हे माँ भवानी, मुझे दुखी, दीन और अपना दास जानकर वैसी ही कृपा कीजिए।"),
 (C,"पुत्र करहिं अपराध बहूता।\nतेहि न धरई चित माता॥","पुत्र बहुत अपराध करता है, पर माता उन्हें मन में नहीं रखती।"),
 (C,"राखु लाज जननि अब मेरी।\nविनय करउं भांति बहु तेरी॥","हे जननी, अब मेरी लाज रखिए; मैं तरह-तरह से आपसे विनती करता हूँ।"),
 (C,"मैं अनाथ तेरी अवलंबा।\nकृपा करउ जय जय जगदंबा॥","मैं अनाथ हूँ, आप ही मेरा सहारा हैं; हे जगदंबा, कृपा कीजिए।"),
 (C,"मधुकैटभ जो अति बलवाना।\nबाहुयुद्ध विष्णु से ठाना॥","मधु और कैटभ, जो बहुत बलवान थे, उन्होंने विष्णु से बाहुयुद्ध किया।"),
 (C,"समर हजार पाँच में घोरा।\nफिर भी मुख उनसे नहीं मोरा॥","पाँच हज़ार वर्ष तक घोर युद्ध चला, फिर भी उन्होंने मुँह नहीं मोड़ा।"),
 (C,"मातु सहाय कीन्ह तेहि काला।\nबुद्धि विपरीत भई खलहाला॥","तब माँ ने सहायता की और उन दुष्टों की बुद्धि उलटी कर दी।"),
 (C,"तेहि ते मृत्यु भई खल केरी।\nपुरवहु मातु मनोरथ मेरी॥","इसी से उन दुष्टों की मृत्यु हुई; हे माँ, मेरा मनोरथ भी पूरा कीजिए।"),
 (C,"चंड मुण्ड जो थे विख्याता।\nक्षण महु संहारे उन माता॥","चंड-मुंड, जो बहुत प्रसिद्ध थे, उन्हें माँ ने क्षण भर में मार डाला।"),
 (C,"रक्त बीज से समरथ पापी।\nसुरमुनि हृदय धरा सब काँपी॥","रक्तबीज जैसे शक्तिशाली पापी से देवता, मुनि और धरती सब काँप उठे थे।"),
 (C,"काटेउ सिर जिमि कदली खम्बा।\nबारबार बिनवउं जगदंबा॥","आपने उसका सिर केले के तने की तरह काट दिया; हे जगदंबा, मैं बार-बार विनती करता हूँ।"),
 (C,"जगप्रसिद्ध जो शुंभनिशुंभा।\nक्षण में बाँधे ताहि तू अम्बा॥","जगत-प्रसिद्ध शुंभ-निशुंभ को भी, हे अम्बा, आपने क्षण भर में बाँध लिया।"),
 (C,"भरतमातु बुद्धि फेरेऊ जाई।\nरामचन्द्र बनवास कराई॥","आपने भरत की माता (कैकेयी) की बुद्धि फेरी और श्रीराम को वनवास करवाया,"),
 (C,"एहिविधि रावण वध तू कीन्हा।\nसुर नरमुनि सबको सुख दीन्हा॥","इस तरह आपने रावण का वध करवाया और देवताओं, मनुष्यों, मुनियों सबको सुख दिया।"),
 (C,"को समरथ तव यश गुन गाना।\nनिगम अनादि अनंत बखाना॥","आपका यश और गुण गाने में कौन समर्थ है? वेदों ने आपको अनादि और अनंत कहा है।"),
 (C,"विष्णु रुद्र जस कहिन मारी।\nजिनकी हो तुम रक्षाकारी॥","विष्णु और रुद्र भी, जिनकी आप रक्षा करती हैं, आपका यश पूरा नहीं कह पाते।"),
 (C,"रक्त दन्तिका और शताक्षी।\nनाम अपार है दानव भक्षी॥","रक्तदंतिका, शताक्षी — दानवों का नाश करने वाली आपके अपार नाम हैं।"),
 (C,"दुर्गम काज धरा पर कीन्हा।\nदुर्गा नाम सकल जग लीन्हा॥","आपने धरती पर कठिन काम किए, इसलिए सारा जगत आपको दुर्गा कहता है।"),
 (C,"दुर्ग आदि हरनी तू माता।\nकृपा करहु जब जब सुखदाता॥","हे माँ, आप संकट हरती हैं; हे सुख देने वाली, जब-जब हो, कृपा कीजिए।"),
 (C,"नृप कोपित को मारन चाहे।\nकानन में घेरे मृग नाहे॥","जब राजा क्रोधित होकर मारना चाहे, या जंगल में शेर घेर ले,"),
 (C,"सागर मध्य पोत के भंजे।\nअति तूफान नहिं कोऊ संगे॥","या समुद्र के बीच नाव टूट जाए, भारी तूफ़ान हो और कोई साथ न हो,"),
 (C,"भूत प्रेत बाधा या दुःख में।\nहो दरिद्र अथवा संकट में॥","भूत-प्रेत की बाधा हो, दुख हो, गरीबी हो या कोई संकट हो,"),
 (C,"नाम जपे मंगल सब होई।\nसंशय इसमें करई न कोई॥","आपका नाम जपने से सब मंगल होता है — इसमें कोई संदेह न करे।"),
 (C,"पुत्रहीन जो आतुर भाई।\nसबै छांड़ि पूजें एहि भाई॥","जो संतान के लिए व्याकुल हो, वह सब छोड़कर इस प्रकार आपकी पूजा करे,"),
 (C,"करै पाठ नित यह चालीसा।\nहोय पुत्र सुन्दर गुण ईशा॥","रोज़ यह चालीसा पढ़े, तो उसे सुंदर और गुणवान संतान मिलती है।"),
 (C,"धूपादिक नैवेद्य चढ़ावै।\nसंकट रहित अवश्य हो जावै॥","धूप आदि और भोग चढ़ाने वाला अवश्य संकटों से मुक्त हो जाता है।"),
 (C,"भक्ति मातु की करैं हमेशा।\nनिकट न आवै ताहि कलेशा॥","जो हमेशा माँ की भक्ति करता है, उसके पास कष्ट नहीं आते।"),
 (C,"बंदी पाठ करें सत बारा।\nबंदी पाश दूर हो सारा॥","जो कैदी सौ बार इसका पाठ करे, उसके सारे बंधन छूट जाते हैं।"),
 (C,"रामसागर बाँधि हेतु भवानी।\nकीजै कृपा दास निज जानी॥","हे भवानी, रामसागर (रचयिता) को अपना दास जानकर कृपा कीजिए।"),
 (D,"मातु सूर्य कान्ति तव, अन्धकार मम रूप।\nडूबन से रक्षा करहु, परूँ न मैं भव कूप॥","हे माँ, आपकी कांति सूर्य जैसी है और मैं अंधकार जैसा हूँ; मुझे डूबने से बचाइए ताकि मैं संसार के कुएँ में न गिरूँ।"),
 (D,"बलबुद्धि विद्या देहु मोहि, सुनहु सरस्वती मातु।\nराम सागर अधम को, आश्रय तू ही देदातु॥","हे माँ सरस्वती, सुनिए — मुझे बल, बुद्धि और विद्या दीजिए; इस अधम रामसागर को आप ही आश्रय दीजिए।"),
]
